// lose is the result code the engine hands to the encounter script
// (through SetParamLose) once the challenge is over.
// The NPC turns to the player, says its line, and the cooldown starts
// only when the code is 1.
local encIndex = CMND_GET_ENCCHR_INDEX();
if (encIndex >= 0)
{
	local mesID = CMND_GET_ENCCHR_TALK_ID(encIndex, lose);
	if (mesID != 0)
	{
		CreateSpeech(mesID);
	}

	if (lose == 1)
	{
		CMND_ADD_ENCCHR_DERAY(encIndex);
	}
}
